/* ==========================================================================
# Audio Blog List style - begin
========================================================================== */
.qode-audio-blog-list {

    .qode-abl-post{
        display: flex;
        align-items: center;
        width: 100%;
        padding: 75px 15%;
        border-bottom: 1px solid #dedede;

        &:last-child{
            border: 0;
        }
    }

    .qode-abl-post-image{
        flex: 0 0 245px;
        margin-right: 55px;
    }

    .qode-abl-info{
        margin-bottom: 5px;

        span{
            text-transform: uppercase;

            a {
                color: inherit;
            }

            &:after{
                content: "·";
                position: relative;
                display: inline-block;
                margin: 0 10px;
            }

            &:last-child:after{
                display: none;
            }
        }
    }

    .qode-abl-post-title{
        margin-bottom: 10px;
    }

    .qode-abl-post-excerpt{
        margin-bottom: 30px;
    }

    .qode-abl-post-link{
        text-transform: uppercase;
        color: inherit;

        i{
            font-size: 24px;
            display: inline-block;
            position: relative;
            margin-right: 10px;
            top: 3px;
        }
    }

    img{
        display: block;
    }

    &.qode-abl-centered{
        .qode-abl-post{
            display: block;
            text-align: center;
        }

        .qode-abl-post-title{
            margin-bottom: 11px;
        }
    }

}
/* ==========================================================================
# Audio Blog List style- end
========================================================================== */